"""
This module keeps the logic for doing bip trace collection and bip mirroring.
The following steps are done for bip collection:

1. Get the common unit type
2. Enable port Mirroring
3. create and start the collector

The CONFIGURATION stucture is:
{'use_script': True|False,
 'gNB_common_unit': ...
 'gNB_capacity_units': [...]
 'l1_type': fs|l1b}
"""
from . import bts_info
from . import bip_config
from . import mirror_asoe
from . import mirror_with_script
from . import admin_mirror
from .tools import python_log
import logging
import re


logger = logging.getLogger()

RUNNING = {}


class BipCollector:
    """ This class provides an interface to the collecting modules.
    It assures, that the commands are called in sequence. If a function
    was called before it is expected to be called, an error messages is
    written to the logs and function of the module is not getting called.
    """

    def __init__(self, module, gnb_id):
        self.module = module
        self.state = 'initialized'
        self.gnb_id = gnb_id

    def start(self):
        self.module.start(gnb_id=self.gnb_id)
        self.state = 'started'

    def stop(self):
        if self.state != 'started':
            logger.error("Collection must be started before stop is called!")
            return
        self.module.stop(gnb_id=self.gnb_id)
        self.state = 'stopped'

    def collect(self, target_dir='/tmp'):
        if self.state != 'stopped':
            logger.error("Collection must be stopped before collect is called!")
            return
        self.state = 'collected'
        return self.module.collect(gnb_id=self.gnb_id, target_dir=target_dir)


def add_running_collection(gnb_id):
    """This function sets a flag, that for the given gnb a bip collection is running and
    defines which module is used for the bip collection.

    :param gnb_id: The gnb_id as index from the list 'gnbs' in the testline configuration
    """
    if gnb_id in RUNNING:
        logger.warn("Trace for gnb_id {} seems already be running!".format(gnb_id))
        return

    system_module = bts_info.get_system_module(gnb_id)

    if system_module == 'ASIM':
        bip_collector = mirror_with_script
    elif bip_config.BIP_CONFIG[gnb_id].get('use_script') is True and system_module != 'ASOE':
        bip_collector = mirror_with_script
    elif bip_config.BIP_CONFIG[gnb_id].get('use_script') is True and system_module == 'ASOE':
        bip_collector = mirror_asoe
    else:
        bip_collector = admin_mirror

    RUNNING[gnb_id] = BipCollector(module=bip_collector, gnb_id=gnb_id)


@python_log
def configure_bip_collection(gnb_id=0, **configuration_params):
    if gnb_id not in bip_config.BIP_CONFIG:
        bip_config.BIP_CONFIG[gnb_id] = {}

    for key in configuration_params:
        if key not in ['script_parameters',
                       'system_module', 'gNB_common_unit',
                       'baseband_modules', 'gNB_capacity_units',
                       'use_script',
                       'collect_separately',
                       'combine_pcaps',
                       'l1_type']:
            logger.warn('Unknown Bip Configuration Key [{}]'.format(key))

    bip_config.BIP_CONFIG[gnb_id].update(**configuration_params)
    bts_info.get_system_module(gnb_id)
    bts_info.get_baseband_modules(gnb_id)
    bts_info.get_sw_version(gnb_id)
    bip_config.log_bip_config()


@python_log
def set_testline_configuration(testline_config):
    bip_config.TL_CONFIG = testline_config


def on_start_robot_suite():
    pass


def on_end_robot_suite():
    """ Callback of robot event listener.
    This function is called, whenever some test suite ends.
    In case of a still running bip collection, the bip collection will be automatically ended.
    The admin library is not checked for this. This is handled by internal flags.
    """
    if RUNNING:
        running_collecors = list(RUNNING.keys())
        for gnb_id in running_collecors:
            if RUNNING[gnb_id].state == 'started':
                logger.warn("End of Suite reached: Stopping BIPTrace for gnb {}".format(gnb_id))
                RUNNING[gnb_id].stop()

            if RUNNING[gnb_id].state == 'stopped':
                logger.warn("End of Suite reached: Collecting BIPTrace for gnb {}".format(gnb_id))
                RUNNING[gnb_id].collect(target_dir='/tmp')


@python_log
def is_bts_version_using_admin(bts_version):
    """ Checks if the given bts_version is already supporting the collection of the bip traces
    with the admin library (taf.sbts.oam.coam.admin).

    The version, from which admin support is expected is SBTS22R4_ENB_9999_220608_000005
    """
    branch, _, version, date, sub_version = bts_version.split('_')
    if branch == 'SBTS22R4':
        return int(date) >= 220608

    branch_match = re.match(r'SBTS(\d+)R(\d+)', branch)
    if branch_match:
        branch_group = branch_match.groups()
        comparable_branch_version = int(branch_group[0]) * 100 + int(branch_group[1])
        return comparable_branch_version >= 2204
    return False


@python_log
def start_bip_trace(gnb_id=0):
    """ This function starts the bip trace collection.
    It checks for the current system module. Based on the system module and the configuration parameters
    the method for obtaining the bip traces is selected.

    All In Cloud Testlines are currently not supported.
    """
    add_running_collection(gnb_id)

    RUNNING[gnb_id].start()


@python_log
def stop_bip_trace(gnb_id=0, target_dir='/tmp'):
    """ This function stops the collection of the bip traces of the given gNodeB
    The resulting pcap files are placed to the target_dir.
    Returned is a list of pcap files.

    :param gnb_id: The gnb_id as index from the list 'gnbs' in the testline configuration
    :param target_dir: The directory the pcaps shall be placed
    """
    if gnb_id not in RUNNING:
        logger.error("Error: Bip Trace for gNodeB {} was not started!".format(gnb_id))
        return

    RUNNING[gnb_id].stop()

    if not bip_config.BIP_CONFIG[gnb_id].get('collect_separately'):
        return collect_bip_trace(gnb_id, target_dir=target_dir)


@python_log
def collect_bip_trace(gnb_id=0, target_dir='/tmp'):
    """ This function collects the bip traces after the bip tracing was stopped.
    It serves for speeding up the stop process, since collection can take some time.
    Returned is a list of pcap files.

    :param gnb_id: The gnb_id as index from the list 'gnbs' in the testline configuration
    :param target_dir: The directory the pcaps shall be placed
    """
    if gnb_id in RUNNING:
        collected_trace = RUNNING.pop(gnb_id).collect(target_dir)
        return collected_trace

    logger.warn("Collect for gNodeB {} was not started or the log was already collected!".format(gnb_id))
